#!/usr/bin/env python3
"""
setup_backend.py
================
Run once from your backend directory to apply every fix and new feature
developed across this session:

    cd /Users/liamcleary/Optimus2-backend-for-credit-AI
    python setup_backend.py

What it does:
  1. Backs up every file it will touch (filename.bak_YYYYMMDD_HHMMSS)
  2. Writes the fixed/new versions of all backend files
  3. Verifies Python files compile cleanly
  4. Prints a summary of what changed and why
"""

import os, sys, shutil, subprocess
from datetime import datetime

HERE = os.path.dirname(os.path.abspath(__file__))

def backup(filename):
    src = os.path.join(HERE, filename)
    if os.path.exists(src):
        ts  = datetime.now().strftime("%Y%m%d_%H%M%S")
        dst = src + f".bak_{ts}"
        shutil.copy2(src, dst)
        return dst
    return None

def write_file(filename, content, is_new=False):
    path = os.path.join(HERE, filename)
    bak  = backup(filename)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    tag = "[NEW]" if is_new else "[UPDATED]"
    bak_note = f"  (backup: {os.path.basename(bak)})" if bak else ""
    print(f"  {tag} {filename}{bak_note}")

def check_python(filename):
    path = os.path.join(HERE, filename)
    result = subprocess.run(
        [sys.executable, "-m", "py_compile", path],
        capture_output=True, text=True
    )
    if result.returncode != 0:
        print(f"  ✗ SYNTAX ERROR in {filename}:")
        print("   ", result.stderr.strip())
        return False
    return True

